rows=[];seen=[]
def run(name,fn):
 start=time.monotonic()
 try:r=fn();status='PASS'
 except Exception as e:r=repr(e);status='FAIL'
 rows.append(dict(case=name,status=status,seconds=round(time.monotonic()-start,3),actual=r));print(rows[-1],flush=True)
class Handler(BaseHTTPRequestHandler):
 def log_message(self,*a):pass
 def do_GET(self):
  seen.append({'path':self.path,'cookie':self.headers.get('Cookie'),'method':self.command,'time':time.monotonic()})
  if self.path=='/bad':self.connection.sendall(b'INVALID HTTP\r\n\r\n');self.close_connection=True;return
  if self.path=='/slow':time.sleep(.4)
  self.send_response(302 if self.path in ('/loop','/external','/redirect') else 200)
  if self.path=='/loop':self.send_header('Location','/loop')
  if self.path=='/external':self.send_header('Location','http://169.254.169.254/')
  if self.path=='/redirect':self.send_header('Location','/')
  self.send_header('Set-Cookie','fixture=Transient');self.end_headers()
  try:self.wfile.write(b'x'*500 if self.path=='/big' else b'local fixture')
  except (BrokenPipeError,ConnectionResetError):pass
server=ThreadingHTTPServer(('127.0.0.1',0),Handler);thread=threading.Thread(target=server.serve_forever);thread.start();url=f'http://127.0.0.1:{server.server_port}';target=validate_target(url,True)
def errorcheck(path):
 try:Client(target,interval=0,timeout=.1).get(url+path)
 except RequestFailure as e:return {'expected':'RequestFailure','error':str(e)}
 raise AssertionError('Expected RequestFailure')
try:
 def basic():
  client=Client(target,interval=0);a=client.get(url+'/redirect');b=client.get(url+'/');assert a.status==b.status==200 and all(r['cookie'] is None for r in seen);return {'redirects':a.redirects,'no_cookie_replay':True}
 run('HTTP same-origin redirect GET only no cookie replay',basic)
 for path in ('/bad','/slow','/loop'):run('HTTP '+path,lambda p=path:errorcheck(p))
 def external():
  r=Client(target,interval=0).get(url+'/external');assert r.status==302 and not r.redirects[0]['followed'];return r.redirects
 run('HTTP external redirect blocked',external)
