  c=Client(target,interval=0,max_requests=1,max_bytes=32);r=c.get(url+'/big');assert len(r.body)==32 and r.truncated
  try:c.get(url+'/')
  except ScanLimit:return {'captured_bytes':len(r.body),'truncated':True,'request_limit':True}
  raise AssertionError('limit not enforced')
 run('HTTP bytes/request limits',limits)
